(function(){
  function strip(s){ return String(s).replace(/<[^>]+>/g,'').trim(); }
  function toMd(html){ var s=String(html);
    s=s.replace(/&amp;/g,'&').replace(/&lt;/g,'<').replace(/&gt;/g,'>').replace(/&quot;/g,'"').replace(/&#39;/g,"'").replace(/&nbsp;/g,' ');
    s=s.replace(/<h([1-6])[^>]*>(.*?)<\/h\1>/gi, function(m,l,t){ return '\n'+'#'.repeat(+l)+' '+strip(t)+'\n'; });
    s=s.replace(/<img[^>]*alt="([^"]*)"[^>]*src="([^"]*)"[^>]*>/gi, function(m,a,src){return '!['+a+']('+src+')';});
    s=s.replace(/<img[^>]*src="([^"]*)"[^>]*alt="([^"]*)"[^>]*>/gi, function(m,src,a){return '!['+a+']('+src+')';});
    s=s.replace(/<img[^>]*src="([^"]*)"[^>]*>/gi, function(m,src){return '![]('+src+')';});
    s=s.replace(/<a[^>]*href="([^"]*)"[^>]*>(.*?)<\/a>/gi, function(m,h,t){return '['+strip(t)+']('+h+')';});
    s=s.replace(/<(strong|b)[^>]*>(.*?)<\/\1>/gi, function(m,t,c){return '**'+strip(c)+'**';});
    s=s.replace(/<(em|i)[^>]*>(.*?)<\/\1>/gi, function(m,t,c){return '*'+strip(c)+'*';});
    s=s.replace(/<code[^>]*>(.*?)<\/code>/gi, function(m,c){return '`'+strip(c)+'`';});
    s=s.replace(/<pre[^>]*>([\s\S]*?)<\/pre>/gi, function(m,c){return '\n```\n'+strip(c)+'\n```\n';});
    s=s.replace(/<blockquote[^>]*>([\s\S]*?)<\/blockquote>/gi, function(m,c){return '\n> '+strip(c).split('\n').join('\n> ')+'\n';});
    s=s.replace(/<ul[^>]*>([\s\S]*?)<\/ul>/gi, function(m,b){ return '\n'+b.replace(/<li[^>]*>(.*?)<\/li>/gi, function(mm,li){return '- '+strip(li)+'\n';}).trim()+'\n'; });
    s=s.replace(/<ol[^>]*>([\s\S]*?)<\/ol>/gi, function(m,b){ var n=0; return '\n'+b.replace(/<li[^>]*>(.*?)<\/li>/gi, function(mm,li){n++;return n+'. '+strip(li)+'\n';}).trim()+'\n'; });
    s=s.replace(/<hr[^>]*>/gi,'\n---\n');
    s=s.replace(/<br[^>]*>/gi,'\n');
    s=s.replace(/<p[^>]*>(.*?)<\/p>/gi, function(m,c){return '\n'+strip(c)+'\n';});
    s=s.replace(/<[^>]+>/g,'');
    s=s.replace(/\n{3,}/g,'\n\n').replace(/^\n+/,'').replace(/\n+$/,'').trim();
    return {value:s}; }
  var API={toMd:toMd};
  if(typeof module!=='undefined'&&module.exports)module.exports=API;
  if(typeof window!=='undefined')window.__HtmlToMdForge__=API;
})();
